module fsm(
    input IN, CLK, RST,
    output reg MATCH
);
    // Define states
    parameter s0 = 3'b000; // Initial state. Detect the 0th MSB 1.
    parameter s1 = 3'b001; // State detecting 1th bit 0.
    parameter s2 = 3'b010; // State detecting 2th bit 0.
    parameter s3 = 3'b011; // State detecting 3th bit 1.
    parameter s4 = 3'b100; // State detecting 4th LSB 1.
    parameter s5 = 3'b101; // State detecting 2th bit 0. This case is check sequences with successive bits `1, 0, 0, 1, 1` such: 1, 0, 0, 1, `1, 0, 0, 1, 1` .
    // State register
    reg [2:0] ST_cr, ST_nt;
    // MATCH logic
    always @(*) begin
        if (ST_cr == s4 && IN)
            MATCH = 1;
        else
            MATCH = 0;
    end
    // State register logic
    always @(posedge CLK or posedge RST) begin
        if (RST) begin
            ST_cr <= s0;
        end else begin
            ST_cr <= ST_nt;
        end
    end
    // Next state logic
    always @(*) begin
        if (ST_cr == s0) begin
            if (IN == 0) begin
                ST_nt = s0;
            end else begin
                ST_nt = s1;
            end
        end else if (ST_cr == s1) begin
            if (IN == 0) begin
                ST_nt = s2;
            end else begin
                ST_nt = s1;
            end
        end else if (ST_cr == s2) begin
            if (IN == 0) begin
                ST_nt = s3;
            end else begin
                ST_nt = s1;
            end
        end else if (ST_cr == s3) begin
            if (IN == 0) begin
                ST_nt = s0;
            end else begin
                ST_nt = s4;
            end
        end else if (ST_cr == s4) begin
            if (IN == 0) begin
                ST_nt = s2;
            end else begin
                ST_nt = s5;
            end
        end else if (ST_cr == s5) begin
            if (IN == 0) begin
                ST_nt = s2;
            end else begin
                ST_nt = s1;
            end
        end else begin
            ST_nt = ST_cr;
        end
    end
endmodule
